using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Microsoft.AspNetCore.Identity;using EMedicine.Api.Data;using EMedicine.Api.Models;using EMedicine.Api.DTOs;using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using System.Text;using Microsoft.IdentityModel.Tokens;
namespace EMedicine.Api.Controllers;
[ApiController][Route("api/auth")]public class AuthController(AppDbContext db,IPasswordHasher<AppUser> hasher,IConfiguration cfg):ControllerBase{
[HttpPost("register")]public async Task<IActionResult> Register(RegisterRequest r){if(string.IsNullOrWhiteSpace(r.Email)||r.Password.Length<8||string.IsNullOrWhiteSpace(r.FirstName))return BadRequest("Valid name, email and password (8+ characters) required");var email=r.Email.Trim().ToLowerInvariant();if(await db.Users.AnyAsync(u=>u.Email==email))return Conflict("Email already registered");var u=new AppUser{FirstName=r.FirstName,LastName=r.LastName,Email=email,Phone=r.Phone};u.PasswordHash=hasher.HashPassword(u,r.Password);db.Users.Add(u);await db.SaveChangesAsync();return Ok(new{u.Id,u.Email});}
[HttpPost("login")]public async Task<IActionResult> Login(LoginRequest r){var u=await db.Users.FirstOrDefaultAsync(x=>x.Email==r.Email.Trim().ToLower());if(u==null||!u.Active||hasher.VerifyHashedPassword(u,u.PasswordHash,r.Password)==PasswordVerificationResult.Failed)return Unauthorized("Invalid credentials");var claims=new[]{new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Role,u.Role),new Claim(ClaimTypes.Email,u.Email)};var token=new JwtSecurityToken(cfg["Jwt:Issuer"],cfg["Jwt:Audience"],claims,expires:DateTime.UtcNow.AddHours(8),signingCredentials:new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(cfg["Jwt:Key"]!)),SecurityAlgorithms.HmacSha256));return Ok(new{token=new JwtSecurityTokenHandler().WriteToken(token),role=u.Role,firstName=u.FirstName});}}
